mockup.css:
.mock-hero-marquee-overflow { background: #f6f4ee; color: #131210;
  font-family: "Helvetica Neue", Inter, ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: center; gap: 3cqw; }
.mock-hero-marquee-overflow .big { font-size: 19cqw; font-weight: 850; line-height: .8; letter-spacing: -.05em;
  white-space: nowrap; margin-inline-start: -6cqw; text-transform: uppercase; }
.mock-hero-marquee-overflow .row { display: flex; justify-content: space-between; align-items: flex-end;
  padding: 0 5cqw; gap: 4cqw; }
.mock-hero-marquee-overflow .row p { margin: 0; max-width: 46%; font-size: 1.95cqw; line-height: 1.45; opacity: .8; }
.mock-hero-marquee-overflow .row .cta { font-size: 1.6cqw; letter-spacing: .12em; text-transform: uppercase;
  border-bottom: 1px solid currentColor; padding-bottom: .5cqw; }
